<?php declare(strict_types=1);namespace App\Core;final class Router{private array $routes=[];public function __construct(private Config $config,private Database $db){} public function get(string $p,array $h,array $mw=[]):void{$this->add('GET',$p,$h,$mw);}public function post(string $p,array $h,array $mw=[]):void{$this->add('POST',$p,$h,$mw);}private function add(string $m,string $p,array $h,array $mw):void{$this->routes[$m][$p]=[$h,$mw];}public function dispatch():void{$path=parse_url($_SERVER['REQUEST_URI']??'/',PHP_URL_PATH)?:'/';$method=$_SERVER['REQUEST_METHOD']??'GET';[$h,$mw]=$this->routes[$method][$path]??[null,null];if(!$h){http_response_code(404);View::render('pages.404');return;}foreach($mw as $class){(new $class($this->db))->handle();}[$class,$action]=$h;(new $class($this->config,$this->db))->$action();}}
